function AdminLoginModal({ onSuccess, onClose }) {
  const [pw, setPw] = useState("");
  const [error, setError] = useState(false);
  const [shake, setShake] = useState(false);

  const handleLogin = () => {
    if (pw === "irishpanget123") {
      onSuccess();
    } else {
      setError(true);
      setShake(true);
      setTimeout(() => setShake(false), 500);
    }
  };

  return (
    <div style={{
      position: "fixed", inset: 0, background: "rgba(80,30,120,0.25)", backdropFilter: "blur(8px)",
      zIndex: 200, display: "flex", alignItems: "center", justifyContent: "center", padding: 16,
    }} onClick={e => e.target === e.currentTarget && onClose()}>
      <div style={{
        background: "rgba(253,245,255,0.98)", borderRadius: 28, width: "min(90vw, 380px)",
        padding: "36px 30px", border: "1.5px solid #e8c8f5",
        boxShadow: "0 20px 80px rgba(120,50,180,0.2)",
        textAlign: "center",
        animation: shake ? "shake 0.4s ease" : "none",
      }}>
        <style>{`@keyframes shake { 0%,100%{transform:translateX(0)} 20%{transform:translateX(-8px)} 40%{transform:translateX(8px)} 60%{transform:translateX(-6px)} 80%{transform:translateX(6px)} }`}</style>
        <div style={{ fontSize: 44, marginBottom: 10 }}>🔐</div>
        <h2 style={{ fontFamily: "'Playfair Display', serif", fontSize: 22, color: "#7a4d9e", marginBottom: 4 }}>Admin Access</h2>
        <p style={{ fontFamily: "'Nunito', sans-serif", fontSize: 13, color: "#b07fd9", marginBottom: 20 }}>Enter your password to continue</p>
        <input
          type="password" placeholder="Password"
          value={pw}
          onChange={e => { setPw(e.target.value); setError(false); }}
          onKeyDown={e => e.key === "Enter" && handleLogin()}
          style={{
            width: "100%", padding: "11px 14px", borderRadius: 14,
            border: `1.5px solid ${error ? "#e05599" : "#e8c8f5"}`,
            fontFamily: "'Nunito', sans-serif", fontSize: 15, color: "#5a3a7e",
            background: "rgba(255,255,255,0.9)", outline: "none",
            boxSizing: "border-box", marginBottom: 8, textAlign: "center",
            letterSpacing: 4,
          }}
          autoFocus
        />
        {error && <p style={{ fontFamily: "'Nunito', sans-serif", fontSize: 13, color: "#d04488", marginBottom: 8 }}>❌ Incorrect password. Try again!</p>}
        <div style={{ display: "flex", gap: 10, marginTop: 8 }}>
          <button onClick={onClose} style={{ flex: 1, background: "transparent", border: "1.5px solid #e8c8f5", color: "#9b5fc0", borderRadius: 14, padding: "10px", cursor: "pointer", fontFamily: "'Nunito', sans-serif", fontSize: 13, fontWeight: 700 }}>Cancel</button>
          <button onClick={handleLogin} style={{ flex: 1, background: "linear-gradient(135deg,#c77dff,#9b5fc0)", color: "#fff", border: "none", borderRadius: 14, padding: "10px", cursor: "pointer", fontFamily: "'Nunito', sans-serif", fontSize: 13, fontWeight: 700, boxShadow: "0 4px 16px rgba(155,95,192,0.35)" }}>
            Enter ✨
          </button>
        </div>
      </div>
    </div>
  );
}

function AdminModal({ data, setData, onClose }) {
  const [tab, setTab] = useState("profile");
  const [local, setLocal] = useState(JSON.parse(JSON.stringify(data)));
  const [picPreview, setPicPreview] = useState(data.profilePic);
  // Track raw comma input for values to avoid cursor bug
  const [valuesRaw, setValuesRaw] = useState(data.intro.values.join(", "));
  const fileRef = useRef();

  const handlePicChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => { setPicPreview(ev.target.result); setLocal(d => ({ ...d, profilePic: ev.target.result })); };
    reader.readAsDataURL(file);
  };

  const updateNested = (section, key, val) => setLocal(d => ({ ...d, [section]: { ...d[section], [key]: val } }));

  const updateAssessmentItem = (i, key, val) => {
    setLocal(d => {
      const items = [...d.assessment.items];
      items[i] = { ...items[i], [key]: val };
      return { ...d, assessment: { ...d.assessment, items } };
    });
  };

  const updateAssessmentScore = (i, j, val) => {
    setLocal(d => {
      const items = d.assessment.items.map((item, idx) => {
        if (idx !== i) return item;
        const scores = [...item.scores];
        scores[j] = parseInt(val) || 0;
        return { ...item, scores };
      });
      return { ...d, assessment: { ...d.assessment, items } };
    });
  };

  const updateYearData = (yearKey, field, val) => {
    setLocal(d => ({
      ...d, evidences: {
        ...d.evidences,
        yearData: {
          ...d.evidences.yearData,
          [yearKey]: { ...d.evidences.yearData[yearKey], [field]: val }
        }
      }
    }));
  };

  const addAssessmentItem = () => setLocal(d => ({
    ...d, assessment: { ...d.assessment, items: [...d.assessment.items, { outcome: "", scores: [0,0,0,0] }] },
  }));

  const removeAssessmentItem = (i) => setLocal(d => ({
    ...d, assessment: { ...d.assessment, items: d.assessment.items.filter((_, idx) => idx !== i) },
  }));

  const tabs = [
    { id: "profile", label: "👤 Profile" },
    { id: "intro", label: "✨ Intro" },
    { id: "assessment", label: "📖 Assessment" },
    { id: "evidences", label: "🌷 Evidences" },
    { id: "reflection", label: "🌸 Reflection" },
    { id: "retrospection", label: "🦋 Retrospection" },
  ];

  const inputStyle = {
    width: "100%", padding: "9px 12px", borderRadius: 12,
    border: "1.5px solid #e8c8f5", fontFamily: "'Nunito', sans-serif",
    fontSize: 13, color: "#5a3a7e", background: "rgba(255,255,255,0.9)",
    outline: "none", boxSizing: "border-box",
  };
  const labelStyle = { fontFamily: "'Nunito', sans-serif", fontSize: 11, fontWeight: 700, color: "#b07fd9", textTransform: "uppercase", letterSpacing: 0.8, marginBottom: 5, display: "block" };

  return (
    <div style={{
      position: "fixed", inset: 0, background: "rgba(80,30,120,0.25)", backdropFilter: "blur(8px)",
      zIndex: 200, display: "flex", alignItems: "center", justifyContent: "center", padding: 16,
    }} onClick={e => e.target === e.currentTarget && onClose()}>
      <div style={{
        background: "rgba(253,245,255,0.98)", borderRadius: 28, width: "min(96vw, 680px)",
        maxHeight: "92vh", display: "flex", flexDirection: "column",
        border: "1.5px solid #e8c8f5",
        boxShadow: "0 20px 80px rgba(120,50,180,0.2)",
      }}>
        <div style={{ padding: "16px 16px 0", borderBottom: "1.5px solid #f0d6ff" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
            <h2 style={{ fontFamily: "'Playfair Display', serif", fontSize: 22, color: "#7a4d9e", margin: 0 }}>⚙️ Admin Panel</h2>
            <button onClick={onClose} style={{ background: "none", border: "none", fontSize: 20, cursor: "pointer", color: "#b07fd9" }}>✕</button>
          </div>
          <div style={{ display: "flex", gap: 4, overflowX: "auto", paddingBottom: 0 }}>
            {tabs.map(t => (
              <button key={t.id} onClick={() => setTab(t.id)} style={{
                background: tab === t.id ? "linear-gradient(135deg,#c77dff,#9b5fc0)" : "transparent",
                color: tab === t.id ? "#fff" : "#9b5fc0",
                border: "none", borderRadius: "12px 12px 0 0",
                padding: "7px 11px", cursor: "pointer", whiteSpace: "nowrap",
                fontFamily: "'Nunito', sans-serif", fontSize: 12, fontWeight: 600,
                transition: "all 0.2s",
              }}>{t.label}</button>
            ))}
          </div>
        </div>

        <div style={{ flex: 1, overflowY: "auto", padding: "16px 16px", display: "flex", flexDirection: "column", gap: 12 }}>
          {tab === "profile" && (
            <>
              <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 6 }}>
                <div style={{
                  width: 72, height: 72, borderRadius: "50%",
                  background: "linear-gradient(135deg,#e8c8f5,#c77dff)",
                  display: "flex", alignItems: "center", justifyContent: "center",
                  overflow: "hidden", flexShrink: 0, border: "2px solid #f0d6ff",
                }}>
                  {picPreview ? <img src={picPreview} style={{ width: "100%", height: "100%", objectFit: "cover" }} alt="" /> : <span style={{ fontSize: 32 }}>🌸</span>}
                </div>
                <div>
                  <input ref={fileRef} type="file" accept="image/*" style={{ display: "none" }} onChange={handlePicChange} />
                  <button onClick={() => fileRef.current.click()} style={{
                    background: "linear-gradient(135deg,#c77dff,#9b5fc0)", color: "#fff",
                    border: "none", borderRadius: 12, padding: "8px 16px",
                    cursor: "pointer", fontFamily: "'Nunito', sans-serif", fontSize: 13, fontWeight: 700,
                  }}>📷 Upload Photo</button>
                  <p style={{ fontFamily: "'Nunito', sans-serif", fontSize: 11, color: "#b07fd9", margin: "5px 0 0" }}>PNG, JPG supported</p>
                </div>
              </div>
              {[["name","Full Name"],["nickname","Nickname"],["birthday","Birthday"],["major","Major"],["faculty","Faculty"],["course","Course"],["school","School"],["year","Year Level"],["email","Email"],["tagline","Tagline"]].map(([k, lbl]) => (
                <div key={k}>
                  <label style={labelStyle}>{lbl}</label>
                  <input style={inputStyle} value={local[k] || ""} onChange={e => setLocal(d => ({ ...d, [k]: e.target.value }))} />
                </div>
              ))}
              <div>
                <label style={labelStyle}>Bio</label>
                <textarea style={{ ...inputStyle, minHeight: 80, resize: "vertical" }} value={local.bio} onChange={e => setLocal(d => ({ ...d, bio: e.target.value }))} />
              </div>
            </>
          )}

          {tab === "intro" && (
            <>
              <div><label style={labelStyle}>Section Title</label><input style={inputStyle} value={local.intro.title} onChange={e => updateNested("intro","title",e.target.value)} /></div>
              <div><label style={labelStyle}>Body Text</label><textarea style={{ ...inputStyle, minHeight: 110, resize: "vertical" }} value={local.intro.body} onChange={e => updateNested("intro","body",e.target.value)} /></div>
              {/* FIX: use raw state to allow typing commas freely */}
              <div>
                <label style={labelStyle}>Core Values (comma-separated)</label>
                <input
                  style={inputStyle}
                  value={valuesRaw}
                  onChange={e => {
                    const raw = e.target.value;
                    setValuesRaw(raw);
                    const parsed = raw.split(",").map(v => v.trim()).filter(Boolean);
                    setLocal(d => ({ ...d, intro: { ...d.intro, values: parsed } }));
                  }}
                />
                <p style={{ fontFamily: "'Nunito', sans-serif", fontSize: 11, color: "#c77dff", margin: "4px 0 0" }}>e.g. Integrity, Compassion, Growth, Service</p>
              </div>
              <div>
                <label style={labelStyle}>Teaching Philosophy</label>
                <textarea style={{ ...inputStyle, minHeight: 130, resize: "vertical" }} value={local.intro.teachingPhilosophy} onChange={e => updateNested("intro","teachingPhilosophy",e.target.value)} />
              </div>
            </>
          )}

          {tab === "assessment" && (
            <>
              <div><label style={labelStyle}>Section Title</label><input style={inputStyle} value={local.assessment.title} onChange={e => updateNested("assessment","title",e.target.value)} /></div>
              <div><label style={labelStyle}>Interpretation Paragraph</label><textarea style={{ ...inputStyle, minHeight: 110, resize: "vertical" }} value={local.assessment.interpretation} onChange={e => updateNested("assessment","interpretation",e.target.value)} /></div>
              {local.assessment.items.map((item, i) => (
                <div key={i} style={{ background: "#fdf0ff", borderRadius: 14, padding: 14, border: "1px solid #f0d6ff" }}>
                  <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 10 }}>
                    <span style={{ fontFamily: "'Nunito', sans-serif", fontSize: 12, color: "#c77dff", fontWeight: 700 }}>Outcome {i + 1}</span>
                    <button onClick={() => removeAssessmentItem(i)} style={{ background: "#ffe0f5", border: "none", borderRadius: 8, padding: "3px 9px", cursor: "pointer", color: "#d04488", fontFamily: "'Nunito', sans-serif", fontSize: 11, fontWeight: 700 }}>🗑</button>
                  </div>
                  <div style={{ marginBottom: 10 }}>
                    <label style={labelStyle}>Outcome Name</label>
                    <input style={inputStyle} value={item.outcome} onChange={e => updateAssessmentItem(i,"outcome",e.target.value)} />
                  </div>
                  <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 8 }}>
                    {["Score 1","Score 2","Score 3","Score 4"].map((lbl, j) => (
                      <div key={j}>
                        <label style={labelStyle}>{lbl}</label>
                        <input type="number" min="0" style={inputStyle} value={item.scores[j]} onChange={e => updateAssessmentScore(i,j,e.target.value)} />
                      </div>
                    ))}
                  </div>
                </div>
              ))}
              <button onClick={addAssessmentItem} style={{ background: "linear-gradient(135deg,#e8c8f5,#d4a8f0)", border: "1.5px dashed #c77dff", borderRadius: 14, padding: "12px", cursor: "pointer", fontFamily: "'Nunito', sans-serif", fontSize: 13, fontWeight: 700, color: "#7a4d9e", width: "100%" }}>
                + Add Outcome
              </button>
            </>
          )}

          {tab === "evidences" && (
            <>
              <div><label style={labelStyle}>Section Title</label><input style={inputStyle} value={local.evidences.title} onChange={e => updateNested("evidences","title",e.target.value)} /></div>
              {["freshman","sophomore","junior","senior"].map(key => {
                const y = local.evidences.yearData[key];
                return (
                  <div key={key} style={{ background: "#fdf0ff", borderRadius: 14, padding: 14, border: "1px solid #f0d6ff" }}>
                    <div style={{ fontFamily: "'Nunito', sans-serif", fontSize: 13, color: "#c77dff", fontWeight: 800, marginBottom: 10, textTransform: "capitalize" }}>
                      {y.emoji} {key} Year
                    </div>
                    <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                      <div><label style={labelStyle}>Year Title</label><input style={inputStyle} value={y.year} onChange={e => updateYearData(key,"year",e.target.value)} /></div>
                      <div><label style={labelStyle}>Subtitle</label><input style={inputStyle} value={y.subtitle} onChange={e => updateYearData(key,"subtitle",e.target.value)} /></div>
                      <div><label style={labelStyle}>Experience</label><textarea style={{ ...inputStyle, minHeight: 80, resize: "vertical" }} value={y.experience} onChange={e => updateYearData(key,"experience",e.target.value)} /></div>
                      <div><label style={labelStyle}>Skills (comma-separated)</label><input style={inputStyle} value={y.skills.join(", ")} onChange={e => updateYearData(key,"skills",e.target.value.split(",").map(s=>s.trim()).filter(Boolean))} /></div>
                    </div>
                  </div>
                );
              })}
            </>
          )}

          {tab === "reflection" && (
            <>
              <div><label style={labelStyle}>Section Title</label><input style={inputStyle} value={local.reflection.title} onChange={e => updateNested("reflection","title",e.target.value)} /></div>
              <div><label style={labelStyle}>Reflection Body</label><textarea style={{ ...inputStyle, minHeight: 140, resize: "vertical" }} value={local.reflection.body} onChange={e => updateNested("reflection","body",e.target.value)} /></div>
              <div><label style={labelStyle}>Lessons Learned (one per line)</label><textarea style={{ ...inputStyle, minHeight: 90, resize: "vertical" }} value={local.reflection.lessons.join("\n")} onChange={e => updateNested("reflection","lessons",e.target.value.split("\n").filter(Boolean))} /></div>
            </>
          )}

          {tab === "retrospection" && (
            <>
              <div><label style={labelStyle}>Section Title</label><input style={inputStyle} value={local.retrospection.title} onChange={e => updateNested("retrospection","title",e.target.value)} /></div>
              <div><label style={labelStyle}>Where I Started</label><textarea style={{ ...inputStyle, minHeight: 90, resize: "vertical" }} value={local.retrospection.past} onChange={e => updateNested("retrospection","past",e.target.value)} /></div>
              <div><label style={labelStyle}>Where I'm Going</label><textarea style={{ ...inputStyle, minHeight: 90, resize: "vertical" }} value={local.retrospection.future} onChange={e => updateNested("retrospection","future",e.target.value)} /></div>
              <div><label style={labelStyle}>Goals (one per line)</label><textarea style={{ ...inputStyle, minHeight: 80, resize: "vertical" }} value={local.retrospection.goals.join("\n")} onChange={e => updateNested("retrospection","goals",e.target.value.split("\n").filter(Boolean))} /></div>
            </>
          )}
        </div>

        <div style={{ padding: "12px 16px 16px", borderTop: "1.5px solid #f0d6ff", display: "flex", gap: 10, justifyContent: "flex-end" }}>
          <button onClick={onClose} style={{ background: "transparent", border: "1.5px solid #e8c8f5", color: "#9b5fc0", borderRadius: 12, padding: "9px 20px", cursor: "pointer", fontFamily: "'Nunito', sans-serif", fontSize: 13, fontWeight: 700 }}>Cancel</button>
          <button onClick={() => { setData(local); onClose(); }} style={{ background: "linear-gradient(135deg,#c77dff,#9b5fc0)", color: "#fff", border: "none", borderRadius: 12, padding: "9px 24px", cursor: "pointer", fontFamily: "'Nunito', sans-serif", fontSize: 13, fontWeight: 700, boxShadow: "0 4px 16px rgba(155,95,192,0.35)" }}>
            💾 Save Changes
          </button>
        </div>
      </div>
    </div>
  );
}

export default function App() {
  const [active, setActive] = useState("Home");
  const [darkMode, setDarkMode] = useState(false);
  const [data, setData] = useState(() => {
    try {
      const version = localStorage.getItem("portfolioVersion");
      if (version !== "irish-v2") {
        localStorage.removeItem("portfolioData");
        localStorage.setItem("portfolioVersion", "irish-v2");
        return defaultData;
      }
      const saved = localStorage.getItem("portfolioData");
      return saved ? JSON.parse(saved) : defaultData;
    } catch {
      return defaultData;
    }
  });
  const [loginOpen, setLoginOpen] = useState(false);
  const [adminOpen, setAdminOpen] = useState(false);

  const handleAdminClick = () => setLoginOpen(true);
  const handleLoginSuccess = () => { setLoginOpen(false); setAdminOpen(true); };

  const handleSetData = (newData) => {
    setData(newData);
    try { localStorage.setItem("portfolioData", JSON.stringify(newData)); } catch {}
  };

  const dm = darkMode;

  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,600;1,400&family=Nunito:wght@400;600;700;800&display=swap');
        * { box-sizing: border-box; margin: 0; padding: 0; }
        body {
          background: ${dm
            ? "linear-gradient(135deg,#0f0a1a 0%,#1a0d2e 40%,#120820 100%)"
            : "linear-gradient(135deg,#fdf4ff 0%,#f5e6ff 40%,#ede0ff 100%)"};
          min-height: 100vh;
          transition: background 0.4s ease;
          color: ${dm ? "#e8d5ff" : "inherit"};
          overflow-x: hidden;
        }
        @keyframes floatUp { from { transform: translateY(0); } to { transform: translateY(-12px); } }
        @keyframes petalFloat { from { transform: translateY(0) rotate(0deg); } to { transform: translateY(-18px) rotate(20deg); } }
        @keyframes togglePop { 0%{transform:scale(1)} 50%{transform:scale(1.3)} 100%{transform:scale(1)} }
        ::-webkit-scrollbar { width: 6px; }
        ::-webkit-scrollbar-track { background: ${dm ? "#1a0d2e" : "#f5e6ff"}; }
        ::-webkit-scrollbar-thumb { background: #c77dff; border-radius: 3px; }
        .desktop-nav { display: flex; }
        .mobile-menu-btn { display: none !important; }
        @media (max-width: 660px) {
          .desktop-nav { display: none !important; }
          .mobile-menu-btn { display: flex !important; }
        }
        @media (max-width: 400px) {
          * { word-break: break-word; }
        }
      `}</style>

      {PETAL_POSITIONS.map((p, i) => <FloatingPetal key={i} {...p} />)}
      <Navbar active={active} setActive={setActive} setAdminOpen={handleAdminClick} name={data.name} darkMode={dm} toggleDarkMode={() => setDarkMode(v => !v)} />

      <div style={{ maxWidth: 900, margin: "0 auto", position: "relative", zIndex: 1, width: "100%", overflowX: "hidden" }}>
        {active === "Home" && <HomeSection data={data} darkMode={dm} />}
        {active === "Intro" && <IntroSection data={data} darkMode={dm} />}
        {active === "Assessment" && <AssessmentSection data={data} darkMode={dm} />}
        {active === "Evidences" && <EvidencesSection data={data} darkMode={dm} />}
        {active === "Reflection" && <ReflectionSection data={data} darkMode={dm} />}
        {active === "Retrospection" && <RetrospectionSection data={data} darkMode={dm} />}
      </div>

      {loginOpen && <AdminLoginModal onSuccess={handleLoginSuccess} onClose={() => setLoginOpen(false)} />}
      {adminOpen && <AdminModal data={data} setData={handleSetData} onClose={() => setAdminOpen(false)} />}
    </>
  );
}
